", "new_string": "import copy
import os
import tomllib

from .defaults import DEFAULTS


_BOOL_TRUE_VALUES = {"1", "true", "yes", "on"}
_BOOL_FALSE_VALUES = {"0", "false", "no", "off"}


def _merge(base, override):
    for key, value in override.items():
        if isinstance(value, dict) and isinstance(base.get(key), dict):
            _merge(base[key], value)
        else:
            base[key] = value
    return base


def _convert_env_value(raw_value, current_value):
    """Convert an environment value to the type of the value it replaces."""
    if isinstance(current_value, bool):
        normalized = str(raw_value).strip().lower()
        if normalized in _BOOL_TRUE_VALUES:
            return True
        if normalized in _BOOL_FALSE_VALUES:
            return False
        raise ValueError(f"invalid boolean value: {raw_value!r}")

    if isinstance(current_value, int):
        return int(raw_value)
    if isinstance(current_value, float):
        return float(raw_value)
    if isinstance(current_value, str):
        return raw_value if isinstance(raw_value, str) else str(raw_value)

    raise TypeError(f"cannot override value of type {type(current_value).__name__}")


def _apply_env_overrides(config, env):
    """Apply ``APP_<SECTION>_<KEY>`` overrides to an already merged config."""
    for section_name, section in config.items():
        if not isinstance(section, dict):
            continue
        for key, current_value in section.items():
            env_name = f"APP_{str(section_name).upper()}_{str(key).upper()}"
            if env_name in env:
                section[key] = _convert_env_value(env[env_name], current_value)


def load_config(path=None, env=None):
    """Return the effective configuration.

    The configuration file is merged over the defaults, then values from the
    environment are applied over that result.  Environment variables use the
    form ``APP_<SECTION>_<KEY>``.
    """
    config = copy.deepcopy(DEFAULTS)
    if path is not None:
        with open(path, "rb") as fh:
            _merge(config, tomllib.load(fh))

    if env is None:
        env = os.environ
    _apply_env_overrides(config, env)
    return config
